import{_ as a,o,c as n,a2 as t}from"./chunks/framework.du4mJiD7.js";const p=JSON.parse('{"title":"Text lives in one JSON file per language and namespace","description":"","frontmatter":{"status":"accepted","date":"2026-10-26T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0014-text-lives-in-one-json-file-per-language-and-namespace.md","filePath":"docs/adr/0014-text-lives-in-one-json-file-per-language-and-namespace.md"}'),s={name:"docs/adr/0014-text-lives-in-one-json-file-per-language-and-namespace.md"};function d(i,e,r,l,c,h){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="text-lives-in-one-json-file-per-language-and-namespace" tabindex="-1">Text lives in one JSON file per language and namespace <a class="header-anchor" href="#text-lives-in-one-json-file-per-language-and-namespace" aria-label="Permalink to &quot;Text lives in one JSON file per language and namespace&quot;">​</a></h1><p>Every word a person reads, on any surface, is written once in <code>i18n/messages/&lt;locale&gt;/&lt;namespace&gt;.json</code>. English is the source; French is the first translation. The namespaces are <code>app</code> (Android and iOS screens), <code>domain</code> (muscles, equipment, units and the other words the shared Kotlin used to hold in <code>Labels</code>), <code>catalog</code> (exercise text, see ADR 0015), and later <code>web</code> and <code>api</code>. Message ids are <code>&lt;group&gt;.&lt;camelCaseName&gt;</code>, the group being the screen or area (<code>library.sortPlanned</code>, <code>muscle.chest</code>), stored as nested JSON, so no id is the prefix of another; catalog ids follow ADR 0015. Plurals and placeholders are ICU MessageFormat with named arguments.</p><p>Until now a string lived in four places (Android <code>values</code> and <code>values-fr</code>, iOS <code>en.lproj</code> and <code>fr.lproj</code>) or in Kotlin code (<code>Labels</code>, the catalog&#39;s <code>{en, fr}</code> pairs), and a third language meant touching all of them. Native speakers who don&#39;t code could not proofread any of it. One file per language lets them work in <a href="https://fink.inlang.com/" target="_blank" rel="noreferrer">Fink</a>, which reads the files through the inlang project in <code>i18n/project.inlang</code> and its next-intl plugin and opens pull requests from a free GitHub account.</p><p>Android and iOS keep their native string files, but they are generated, never committed: a Gradle task (registered in <code>build-logic</code>, implemented in <code>tools/i18n</code>) turns the JSON into <code>strings.xml</code>, <code>.strings</code> and <code>.stringsdict</code> under <code>build/generated</code>, rewriting named ICU arguments as positional ones in order of first appearance. Xcode already runs Gradle to build the shared framework, so no build needs Node. The same task writes a Kotlin source holding the <code>domain</code> text, which the shared code looks up by id instead of the hand-written <code>Labels</code>, the way ADR 0012 generates the theme from one file.</p><p>The server words only what it sends itself (emails, notifications, exports) from the <code>api</code> namespace, and returns errors as codes the clients translate.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A new string is added to <code>i18n/messages/en</code> and <code>i18n/messages/fr</code>; a new language is one folder of files plus its locale in the inlang settings.</li><li><code>LocalizedText</code> becomes a map from language to text that falls back to English, so the model no longer names its languages.</li><li>The JSON holds no notes. A message that needs context for translators gets a note in <code>i18n/glossary/en.md</code>, beside the per-language glossaries in <code>i18n/glossary/&lt;locale&gt;.md</code>.</li><li>CI fails when a message is missing in a locale the app ships.</li></ul><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Keep native files as the source</strong>: no proofreading tool reads Android, iOS and the catalog together, and the web and server would need a fourth copy.</li><li><strong>Read the JSON at runtime in shared Kotlin</strong>: one code path, but plural rules and formatting would need an ICU implementation in Kotlin; the platforms already have one.</li><li><strong>A Node generator beside <code>design/build-tokens.mjs</code></strong>: would put Node in the iOS and Android builds, which today need only the JDK.</li></ul>',9)])])}const u=a(s,[["render",d]]);export{p as __pageData,u as default};
